/* ========================================
 Exercice 1 :
 ========================================
Écrire un programme en C qui demande à l'utilisateur de saisir une note sur
20. Le programme doit afficher une appréciation selon les règles suivantes :
note < 10 → « Insuffisant » ; 10 ≤ note < 12 → « Passable » ; 12 ≤ note < 14
→ « Assez bien » ; 14 ≤ note < 16 → « Bien » ; note ≥ 16 → « Très bien ». Le
programme doit également vérifier que la note saisie est comprise entre 0 et
20. Si ce n'est pas le cas, afficher : Note invalide
*/

#include <stdio.h>

int main(void)
{
    float note;

    printf("Entrez une note sur 20 : ");
    scanf("%f", &note);

    if (note < 0 || note > 20) {
        printf("Note invalide\n");
    } else if (note < 10) {
        printf("Insuffisant\n");
    } else if (note < 12) {
        printf("Passable\n");
    } else if (note < 14) {
        printf("Assez bien\n");
    } else if (note < 16) {
        printf("Bien\n");
    } else {
        printf("Tres bien\n");
    }
    return 0;
}

/* ========================================
 Exercice 2 :
 ========================================
Écrire un programme qui demande un entier N puis calcule la somme des
nombres de 1 à N.

Exemple :
    N = 5
    1 + 2 + 3 + 4 + 5 = 15
*/

#include <stdio.h>

int main(void)
{
    int n, i, somme = 0;

    printf("Entrez N : ");
    scanf("%d", &n);

    for (i = 1; i <= n; i++) {
        somme = somme + i;
    }

    printf("La somme de 1 a %d vaut %d\n", n, somme);
    return 0;
}

/* ========================================
 Exercice 3 :
 ========================================
On souhaite créer un petit menu permettant de gérer l'état d'un serveur.
Écrire un programme en C qui affiche le menu suivant :

===== GESTION DU SERVEUR =====
1. Démarrer le serveur
2. Arrêter le serveur
3. Redémarrer le serveur
4. Afficher l'état du serveur
5. Quitter

Votre choix :

Le programme demande à l'utilisateur de saisir un choix entre 1 et 5. Selon le choix :
*/

#include <stdio.h>

int main(void)
{
    int choix;

    printf("===== GESTION DU SERVEUR =====\n");
    printf("1. Demarrer le serveur\n");
    printf("2. Arreter le serveur\n");
    printf("3. Redemarrer le serveur\n");
    printf("4. Afficher l'etat du serveur\n");
    printf("5. Quitter\n\n");
    printf("Votre choix : ");
    scanf("%d", &choix);

    switch (choix) {

        // 1. 1 → afficher « Le serveur démarre... »
        case 1: printf("Le serveur demarre...\n");    break;

        // 2. 2 → afficher « Le serveur s'arrête... »
        case 2: printf("Le serveur s'arrete...\n");   break;

        // 3. 3 → afficher « Le serveur redémarre... »
        case 3: printf("Le serveur redemarre...\n");  break;

        // 4. 4 → afficher « État du serveur : ACTIF »
        case 4: printf("Etat du serveur : ACTIF\n");  break;

        // 5. 5 → afficher « Au revoir »
        case 5: printf("Au revoir\n");                break;

        // 6. tout autre choix → afficher « Choix invalide »
        default: printf("Choix invalide\n");
    }
    return 0;
}

/* ========================================
 Exercice 4 :
 ========================================
Écrire un programme qui demande à l'utilisateur de saisir un nombre entier
positif, puis affiche ce nombre à l'envers. Le programme doit d'abord
vérifier que le nombre saisi est positif : si le nombre est positif, le
programme affiche son inverse ; sinon, il affiche le message « Erreur : le
nombre doit être positif. »

Exemple :
    Entrez un nombre : 12345
    Nombre inversé : 54321
*/

#include <stdio.h>

int main(void)
{
    int nombre, inverse = 0, chiffre;

    printf("Entrez un nombre : ");
    scanf("%d", &nombre);

    if (nombre <= 0) {
        printf("Erreur : le nombre doit etre positif.\n");
        return 0;
    }

    while (nombre > 0) {
        chiffre = nombre % 10;            /* le dernier chiffre */
        inverse = inverse * 10 + chiffre; /* on le pousse à gauche */
        nombre  = nombre / 10;            /* on le retire du nombre */
    }

    printf("Nombre inverse : %d\n", inverse);
    return 0;
}

/* ========================================
 Exercice 5 :
 ========================================
Écrire un programme en C mettant en œuvre le jeu suivant : le premier
utilisateur saisit un entier que le second utilisateur doit deviner. Le
second utilisateur peut effectuer autant de tentatives qu'il le souhaite. À
chaque tentative, il saisit une proposition. Après chaque échec : si la
proposition est plus petite que le nombre recherché, le programme indique
que le nombre à trouver est plus grand ; si la proposition est plus grande,
il indique que le nombre à trouver est plus petit. Le programme doit
également compter le nombre de tentatives effectuées. Lorsque le nombre est
trouvé, le programme affiche un message de félicitations ainsi que le score
correspondant au nombre de coups joués.
*/

#include <stdio.h>

int main(void)
{
    int secret, proposition, tentatives = 0;

    printf("Joueur 1, entrez le nombre a deviner : ");
    scanf("%d", &secret);

    do {
        printf("Proposition : ");
        scanf("%d", &proposition);
        tentatives++;

        if (proposition < secret) {
            printf("  C'est plus grand.\n");
        } else if (proposition > secret) {
            printf("  C'est plus petit.\n");
        }
    } while (proposition != secret);

    printf("Bravo ! Trouve en %d coup(s).\n", tentatives);
    return 0;
}

/* ========================================
 Exercice 6 :
 ========================================
Écrire un programme qui demande à l'utilisateur de saisir un nombre, et de
vérifier si ce nombre est presque parfait ou non. On appelle nombre presque
parfait un entier naturel dont la somme des diviseurs hormis lui-même est
inférieure de 1 à lui-même. Par exemple, 16 est un nombre presque parfait :
1+2+4+8 = 15 = 16−1.
*/

#include <stdio.h>

int main(void)
{
    int n, i, somme = 0;

    printf("Entrez un nombre : ");
    scanf("%d", &n);

    for (i = 1; i < n; i++) {      /* i < n : on exclut n lui-même */
        if (n % i == 0) {
            somme = somme + i;
        }
    }

    printf("Somme des diviseurs propres : %d\n", somme);

    if (somme == n - 1) {
        printf("%d est presque parfait.\n", n);
    } else {
        printf("%d n'est pas presque parfait.\n", n);
    }
    return 0;
}

/* ========================================
 Exercice 7 :
 ========================================
Écrire un programme qui permet de saisir un entier de trois chiffres non
nuls, de déterminer et d'afficher tous les nombres qui peuvent être formés
par les chiffres de N.

Exemple :
    N = 578
    Les nombres formés par les chiffres de N sont : 578, 587, 785, 758, 857, 875.
*/

#include <stdio.h>

int main(void)
{
    int n, c1, c2, c3;

    printf("Entrez un entier de trois chiffres non nuls : ");
    scanf("%d", &n);

    if (n < 100 || n > 999) {
        printf("Erreur : il faut trois chiffres.\n");
        return 0;
    }

    c1 = n / 100;          /* centaines */
    c2 = (n / 10) % 10;    /* dizaines  */
    c3 = n % 10;           /* unités    */

    if (c1 == 0 || c2 == 0 || c3 == 0) {
        printf("Erreur : les trois chiffres doivent etre non nuls.\n");
        return 0;
    }

    printf("%d %d %d %d %d %d\n",
           c1*100 + c2*10 + c3,  c1*100 + c3*10 + c2,
           c2*100 + c1*10 + c3,  c2*100 + c3*10 + c1,
           c3*100 + c1*10 + c2,  c3*100 + c2*10 + c1);
    return 0;
}

/* ========================================
 Exercice 1 :
 ========================================
Écrire une fonction Moyenne qui reçoit deux nombres réels et retourne leur
moyenne.

Exemple :
    Saisir la première mesure : 18.5
    Saisir la deuxième mesure : 21.5

    La moyenne est : 20.00
*/

#include <stdio.h>

float Moyenne(float a, float b)
{
    return (a + b) / 2;
}

int main(void)
{
    float m1, m2;

    // 1. Demander à l'utilisateur de saisir deux mesures.
    printf("Saisir la première mesure : ");
    scanf("%f", &m1);
    printf("Saisir la deuxième mesure : ");
    scanf("%f", &m2);

    // 2. Appeler la fonction Moyenne.
    // 3. Afficher la moyenne calculée.
    printf("\nLa moyenne est : %.2f\n", Moyenne(m1, m2));
    return 0;
}

/* ========================================
 Exercice 2 :
 ========================================
Écrire une fonction EstValide qui reçoit un entier représentant une valeur
d'un octet IPv4 et retourne 1 si la valeur est comprise entre 0 et 255, 0
sinon. Le programme principal doit demander une valeur et utiliser la
fonction pour vérifier si elle peut représenter un octet d'une adresse IPv4.

Exemple :
    Saisir une valeur : 192
    La valeur est valide.

    Saisir une valeur : 300
    La valeur est invalide.
*/

#include <stdio.h>

int EstValide(int valeur)
{
    if (valeur >= 0 && valeur <= 255)
    {
        return 1;
    }
    return 0;
}

int main(void)
{
    int valeur;

    printf("Saisir une valeur : ");
    scanf("%d", &valeur);

    if (EstValide(valeur))
    {
        printf("La valeur est valide.\n");
    }
    else
    {
        printf("La valeur est invalide.\n");
    }
    return 0;
}

/* ========================================
 Exercice 3 :
 ========================================
Écrire une fonction CalculerDebit qui reçoit la taille d'un fichier en Mo et
le temps de téléchargement en secondes. La fonction retourne le débit moyen
en Mo/s. Le programme principal doit demander les deux valeurs, appeler la
fonction et afficher le débit.

Exemple :
    Taille du fichier : 120
    Temps de téléchargement : 10

    Débit moyen : 12.00 Mo/s
*/

#include <stdio.h>

float CalculerDebit(float taille, float temps)
{
    return taille / temps;
}

int main(void)
{
    float taille, temps;

    printf("Taille du fichier : ");
    scanf("%f", &taille);
    printf("Temps de téléchargement : ");
    scanf("%f", &temps);

    printf("\nDébit moyen : %.2f Mo/s\n", CalculerDebit(taille, temps));
    return 0;
}

/* ========================================
 Exercice 4 :
 ========================================
Écrire une fonction CalculerTauxPerte qui reçoit le nombre de paquets
envoyés et le nombre de paquets perdus. La fonction retourne le taux de
perte en pourcentage.

Exemple :
    Nombre de paquets envoyés : 500
    Nombre de paquets perdus : 25

    Taux de perte : 5.00 %
*/

#include <stdio.h>

float CalculerTauxPerte(int envoyes, int perdus)
{
    return (float) perdus / envoyes * 100;
}

int main(void)
{
    int envoyes, perdus;

    // 1. Demander à l'utilisateur le nombre de paquets envoyés.
    printf("Nombre de paquets envoyés : ");
    scanf("%d", &envoyes);

    // 2. Demander le nombre de paquets perdus.
    printf("Nombre de paquets perdus : ");
    scanf("%d", &perdus);

    // 3. Appeler la fonction CalculerTauxPerte.
    // 4. Afficher le taux de perte.
    printf("\nTaux de perte : %.2f %%\n", CalculerTauxPerte(envoyes, perdus));
    return 0;
}

/* ========================================
 Exercice 5 :
 ========================================
Un technicien relève la température d'un équipement réseau pendant 7 jours.

Exemple :
    Températures relevées :
*/

#include <stdio.h>

int main(void)
{

    // 1. Déclare un tableau temperatures de 7 nombres réels.
    float temperatures[7];
    float somme = 0.0f;
    int i;

    // 2. Demande à l'utilisateur de saisir les 7 températures.
    for (i = 0; i < 7; i++)
    {
        printf("Température %d : ", i + 1);
        scanf("%f", &temperatures[i]);
        somme = somme + temperatures[i];
    }

    // 3. Affiche toutes les températures saisies.
    printf("\nTempératures relevées :\n");
    for (i = 0; i < 7; i++)
    {
        printf("%.1f  ", temperatures[i]);
    }

    // 4. Calcule et affiche la température moyenne.
    printf("\n\nTempérature moyenne : %.1f °C\n", somme / 7);
    return 0;
}

/* ========================================
 Exercice 8 :
 ========================================
Un administrateur relève l'utilisation du processeur d'un serveur pendant 10
mesures. On dispose d'un tableau contenant les pourcentages d'utilisation
CPU.

Exemple :
    Utilisation CPU :
    45  52  61  70  55  48  63  72  68  50

    Utilisation moyenne : 58.40 %
    Utilisation maximale : 72 %
*/

#include <stdio.h>

void  SaisirTableau(float t[], int n);
void  AfficherTableau(float t[], int n);
float CalculerMoyenne(float t[], int n);
float Maximum(float t[], int n);

int main(void)
{
    float cpu[10];

    SaisirTableau(cpu, 10);

    printf("\nUtilisation CPU :\n");
    AfficherTableau(cpu, 10);

    printf("\n\nUtilisation moyenne : %.2f %%\n", CalculerMoyenne(cpu, 10));
    printf("Utilisation maximale : %.0f %%\n", Maximum(cpu, 10));
    return 0;
}

// 1. SaisirTableau() : permet de remplir le tableau ;
void SaisirTableau(float t[], int n)
{
    int i;
    for (i = 0; i < n; i++)
    {
        printf("Mesure %d : ", i + 1);
        scanf("%f", &t[i]);
    }
}

// 2. AfficherTableau() : affiche les valeurs ;
void AfficherTableau(float t[], int n)
{
    int i;
    for (i = 0; i < n; i++)
    {
        printf("%.0f  ", t[i]);
    }
}

// 3. CalculerMoyenne() : retourne la moyenne des valeurs ;
float CalculerMoyenne(float t[], int n)
{
    float somme = 0.0f;
    int i;
    for (i = 0; i < n; i++)
    {
        somme = somme + t[i];
    }
    return somme / n;
}

// 4. Maximum() : retourne la valeur maximale.
float Maximum(float t[], int n)
{
    float max = t[0];
    int i;
    for (i = 1; i < n; i++)
    {
        if (t[i] > max)
        {
            max = t[i];
        }
    }
    return max;
}

