/* ========================================
 Exercice 1 :
 ========================================
Un administrateur réseau souhaite analyser le nombre de connexions établies
entre 4 serveurs. On utilise une matrice 4 × 4 : chaque ligne représente le
serveur qui établit la connexion, chaque colonne le serveur destinataire, et
chaque case contient le nombre de connexions.

Écrire un programme en langage C qui :
    1. Déclare une matrice de 4 × 4 entiers.
    2. Demande à l'utilisateur de saisir les valeurs de la matrice.
    3. Affiche la matrice sous forme de tableau.
    4. Calcule et affiche le nombre total de connexions établies entre tous
       les serveurs.
    5. Calcule et affiche le nombre total de connexions établies par chaque
       serveur.
*/

#include <stdio.h>

#define N 4

int main(void)
{
    // 1. Déclare une matrice de 4 × 4 entiers.
    int connexions[N][N];
    int i, j, total = 0;

    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++) {
            // 2. Demande à l'utilisateur de saisir les valeurs de la matrice.
            printf("Connexions du serveur %d vers le serveur %d : ", i + 1, j + 1);
            scanf("%d", &connexions[i][j]);
        }
    }

    // 3. Affiche la matrice sous forme de tableau.
    printf("\nMatrice des connexions :\n");
    for (i = 0; i < N; i++) {
        for (j = 0; j < N; j++)
            printf("%5d", connexions[i][j]);
        printf("\n");
    }

    for (i = 0; i < N; i++)
        for (j = 0; j < N; j++)
            total += connexions[i][j];
    // 4. Calcule et affiche le nombre total de connexions établies entre tous les serveurs.
    printf("\nTotal des connexions : %d\n", total);

    // 5. Calcule et affiche le nombre total de connexions établies par chaque serveur.
    printf("\nConnexions etablies par chaque serveur :\n");
    for (i = 0; i < N; i++) {
        int somme = 0;
        for (j = 0; j < N; j++)
            somme += connexions[i][j];
        printf("  serveur %d : %d\n", i + 1, somme);
    }
    return 0;
}

/* ========================================
 Exercice 2 :
 ========================================
Une entreprise souhaite surveiller la température de ses serveurs pendant 5
jours. Pour chaque jour, on mesure la température de 4 serveurs. On utilise
donc une matrice 5 × 4 : chaque ligne représente un jour, chaque colonne un
serveur, et chaque case la température mesurée en °C.

Écrire un programme en langage C qui :
    1. Déclare une matrice 5 × 4 de nombres réels (float).
    2. Demande à l'utilisateur de saisir les températures.
    3. Affiche toutes les températures sous forme de matrice.
    4. Calcule et affiche la température moyenne de chaque serveur.
    5. Compte le nombre de températures supérieures à 30 °C.
    6. Affiche la température maximale enregistrée.
*/

#include <stdio.h>

#define JOURS    5
#define SERVEURS 4

int main(void)
{
    // 1. Déclare une matrice 5 × 4 de nombres réels (float).
    float temperatures[JOURS][SERVEURS];
    int i, j, chaudes = 0;
    float maximum;

    for (i = 0; i < JOURS; i++) {
        for (j = 0; j < SERVEURS; j++) {
            // 2. Demande à l'utilisateur de saisir les températures.
            printf("Jour %d, serveur %d : ", i + 1, j + 1);
            scanf("%f", &temperatures[i][j]);
        }
    }

    // 3. Affiche toutes les températures sous forme de matrice.
    printf("\nReleve des temperatures :\n");
    for (i = 0; i < JOURS; i++) {
        for (j = 0; j < SERVEURS; j++)
            printf("%8.1f", temperatures[i][j]);
        printf("\n");
    }

    // 4. Calcule et affiche la température moyenne de chaque serveur.
    printf("\nTemperature moyenne de chaque serveur :\n");
    for (j = 0; j < SERVEURS; j++) {
        float somme = 0;
        for (i = 0; i < JOURS; i++)
            somme += temperatures[i][j];
        printf("  serveur %d : %.2f C\n", j + 1, somme / JOURS);
    }

    maximum = temperatures[0][0];
    for (i = 0; i < JOURS; i++)
        for (j = 0; j < SERVEURS; j++) {
            if (temperatures[i][j] > 30.0)
                chaudes++;
            if (temperatures[i][j] > maximum)
                maximum = temperatures[i][j];
        }

    // 5. Compte le nombre de températures supérieures à 30 °C.
    printf("\nReleves au-dessus de 30 C : %d\n", chaudes);
    // 6. Affiche la température maximale enregistrée.
    printf("Temperature maximale : %.1f C\n", maximum);
    return 0;
}

/* ========================================
 Exercice 3 :
 ========================================
Un administrateur réseau souhaite analyser les tentatives de connexion
effectuées sur 4 comptes utilisateurs pendant 5 jours. On utilise un tableau
à deux dimensions 4 × 5 : chaque ligne représente un utilisateur, chaque
colonne un jour, et chaque case le nombre de tentatives de connexion
effectuées par un utilisateur pendant un jour.

Écrire un programme en langage C qui permet de :
    1. Déclarer un tableau à deux dimensions de 4 lignes et 5 colonnes.
    2. Demander à l'utilisateur de saisir le nombre de tentatives de
       connexion pour chaque utilisateur et chaque jour.
    3. Afficher le tableau.
    4. Créer une fonction totalUtilisateur() qui reçoit le tableau et le
       numéro d'une ligne et qui retourne le nombre total de tentatives de
       connexion de l'utilisateur correspondant.
    5. Appeler cette fonction pour chaque utilisateur et afficher son
       nombre total de tentatives.
    6. Déterminer et afficher l'utilisateur ayant effectué le plus grand
       nombre de tentatives de connexion.
*/

#include <stdio.h>

#define UTILISATEURS 4
#define JOURS        5

int totalUtilisateur(int tentatives[][JOURS], int ligne);

int main(void)
{
    // 1. Déclarer un tableau à deux dimensions de 4 lignes et 5 colonnes.
    int tentatives[UTILISATEURS][JOURS];
    int i, j, total, meilleur = 0, record;

    for (i = 0; i < UTILISATEURS; i++) {
        for (j = 0; j < JOURS; j++) {
            // 2. Demander à l'utilisateur de saisir le nombre de tentatives de connexion pour chaque utilisateur et chaque jour.
            printf("Utilisateur %d, jour %d : ", i + 1, j + 1);
            scanf("%d", &tentatives[i][j]);
        }
    }

    // 3. Afficher le tableau.
    printf("\nTentatives de connexion :\n");
    for (i = 0; i < UTILISATEURS; i++) {
        for (j = 0; j < JOURS; j++)
            printf("%5d", tentatives[i][j]);
        printf("\n");
    }

    // 5. Appeler cette fonction pour chaque utilisateur et afficher son nombre total de tentatives.
    printf("\nTotal par utilisateur :\n");
    record = totalUtilisateur(tentatives, 0);
    for (i = 0; i < UTILISATEURS; i++) {
        total = totalUtilisateur(tentatives, i);
        printf("  utilisateur %d : %d tentative(s)\n", i + 1, total);
        if (total > record) {
            record = total;
            meilleur = i;
        }
    }

    // 6. Déterminer et afficher l'utilisateur ayant effectué le plus grand nombre de tentatives de connexion.
    printf("\nPlus grand nombre de tentatives : utilisateur %d (%d)\n",
           meilleur + 1, record);
    return 0;
}

// 4. Créer une fonction totalUtilisateur() qui reçoit le tableau et le numéro d'une ligne et qui retourne le nombre total de tentatives de connexion de l'utilisateur correspondant.
int totalUtilisateur(int tentatives[][JOURS], int ligne)
{
    int j, somme = 0;
    for (j = 0; j < JOURS; j++)
        somme += tentatives[ligne][j];
    return somme;
}

/* ========================================
 Exercice 1 :
 ========================================
Un technicien relève 8 mesures provenant d'un équipement. On dispose du
tableau :

int mesures[8] = {12, 18, 7, 25, 14, 9, 21, 16};

Écrire un programme qui :
    1. Déclare le tableau.
    2. Déclare un pointeur p.
    3. Initialise p avec l'adresse du premier élément du tableau.
    4. Parcourt le tableau uniquement à l'aide du pointeur.
    5. Affiche chaque mesure.
    6. Calcule la somme des mesures.
    7. Affiche la plus grande mesure.
*/

#include <stdio.h>

int main(void)
{
    // 1. Déclare le tableau.
    int mesures[8] = {12, 18, 7, 25, 14, 9, 21, 16};
    // 2. Déclare un pointeur p.
    // 3. Initialise p avec l'adresse du premier élément du tableau.
    int *p = mesures;          /* 3. p recoit l'adresse du premier element */
    int somme = 0;
    int maxi;
    int i;

    maxi = *p;                 /* on part de la premiere mesure, pas de 0 */

    // 4. Parcourt le tableau uniquement à l'aide du pointeur.
    for (i = 0; i < 8; i++) {  /* 4. on ne parcourt QU'AVEC le pointeur */
        // 5. Affiche chaque mesure.
        printf("mesure %d : %d\n", i + 1, *p);
        // 6. Calcule la somme des mesures.
        somme += *p;
        if (*p > maxi)
            maxi = *p;
        p++;
    }

    printf("somme            : %d\n", somme);
    // 7. Affiche la plus grande mesure.
    printf("plus grande      : %d\n", maxi);
    return 0;
}

/* ========================================
 Exercice 2 :
 ========================================
Un programme doit permettre à l'utilisateur de saisir une série de valeurs.
Le nombre de valeurs n'est pas connu à l'avance.

Écrire un programme qui :
    1. Demande à l'utilisateur le nombre de valeurs à saisir.
    2. Déclare un pointeur p.
    3. Utilise malloc() pour réserver la mémoire nécessaire.
    4. Demande les valeurs à l'utilisateur.
    5. Affiche les valeurs saisies.
    6. Calcule la somme.
    7. Affiche la moyenne.
    8. Libère la mémoire avec free().
*/

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    // 2. Déclare un pointeur p.
    int *p;
    int n, i, somme = 0;

    // 1. Demande à l'utilisateur le nombre de valeurs à saisir.
    printf("Combien de valeurs ? ");
    scanf("%d", &n);

    // 3. Utilise malloc() pour réserver la mémoire nécessaire.
    p = malloc(n * sizeof(int));
    if (p == NULL) {
        printf("Allocation impossible\n");
        return 1;
    }

    for (i = 0; i < n; i++) {
        // 4. Demande les valeurs à l'utilisateur.
        printf("valeur %d : ", i + 1);
        scanf("%d", &p[i]);
    }

    // 5. Affiche les valeurs saisies.
    printf("\nValeurs saisies :\n");
    for (i = 0; i < n; i++) {
        printf("%d\n", p[i]);
        // 6. Calcule la somme.
        somme += p[i];
    }

    printf("somme   : %d\n", somme);
    // 7. Affiche la moyenne.
    printf("moyenne : %.2f\n", (float)somme / n);

    // 8. Libère la mémoire avec free().
    free(p);
    return 0;
}

/* ========================================
 Exercice : chercher une valeur
 ========================================
On souhaite créer un programme permettant de rechercher une valeur dans une
série de données.

Le programme doit :
    1. Demander à l'utilisateur le nombre de valeurs.
    2. Réserver dynamiquement la mémoire avec malloc().
    3. Remplir la zone mémoire avec les valeurs saisies.
    4. Demander une valeur à rechercher.
    5. Parcourir les données à l'aide du pointeur.
    6. Indiquer si la valeur existe ou non.
    7. Si elle existe, afficher sa position.
    8. Libérer la mémoire avec free().
*/

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *p;
    int n, i, cherchee, position = -1;

    // 1. Demander à l'utilisateur le nombre de valeurs.
    printf("Combien de valeurs ? ");
    scanf("%d", &n);

    // 2. Réserver dynamiquement la mémoire avec malloc().
    p = malloc(n * sizeof(int));
    if (p == NULL) {
        printf("Allocation impossible\n");
        return 1;
    }

    // 3. Remplir la zone mémoire avec les valeurs saisies.
    for (i = 0; i < n; i++) {
        printf("valeur %d : ", i + 1);
        scanf("%d", &p[i]);
    }

    // 4. Demander une valeur à rechercher.
    printf("Valeur a rechercher : ");
    scanf("%d", &cherchee);

    // 5. Parcourir les données à l'aide du pointeur.
    for (i = 0; i < n; i++) {
        if (p[i] == cherchee) {
            position = i;
            break;
        }
    }

    // 6. Indiquer si la valeur existe ou non.
    // 7. Si elle existe, afficher sa position.
    if (position == -1)
        printf("%d ne figure pas dans la serie\n", cherchee);
    else
        printf("%d est a la position %d (le %d-eme)\n", cherchee, position, position + 1);

    // 8. Libérer la mémoire avec free().
    free(p);
    return 0;
}

/* ========================================
 Exercice 4 :
 ========================================
Un système industriel récupère les mesures d'un capteur à intervalles
réguliers. Le nombre de mesures à enregistrer n'est pas connu à l'avance :
il est saisi par l'utilisateur au début du programme. Écrire un programme en
langage C qui permet de gérer ces mesures.
*/

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    float *mesures;
    float somme = 0, mini, maxi;
    int n, i;

    // 1. Demander à l'utilisateur le nombre de mesures à enregistrer.
    printf("Combien de mesures ? ");
    scanf("%d", &n);

    // 2. Allouer dynamiquement un tableau de float permettant de stocker ces
    //    mesures. L'allocation devra être réalisée avec la fonction calloc.
    mesures = calloc(n, sizeof(float));   /* calloc : n objets, chacun de sizeof(float) */

    // 3. Vérifier que l'allocation mémoire a réussi.
    if (mesures == NULL) {
        printf("Allocation impossible\n");
        return 1;
    }

    // 4. Demander à l'utilisateur de saisir les différentes mesures.
    for (i = 0; i < n; i++) {
        printf("mesure %d : ", i + 1);
        scanf("%f", &mesures[i]);
    }

    mini = maxi = mesures[0];               /* on part de la premiere mesure */

    // 5. Afficher toutes les mesures enregistrées en utilisant un pointeur.
    printf("\nMesures enregistrees :\n");
    for (i = 0; i < n; i++) {
        printf("%.2f\n", mesures[i]);
        somme += mesures[i];
        if (mesures[i] < mini) mini = mesures[i];
        if (mesures[i] > maxi) maxi = mesures[i];
    }

    // 6. Calculer et afficher : la moyenne des mesures ; la valeur minimale
    //    ; la valeur maximale.
    printf("moyenne  : %.2f\n", somme / n);
    printf("minimale : %.2f\n", mini);
    printf("maximale : %.2f\n", maxi);

    // 7. Libérer la mémoire allouée dynamiquement à l'aide de free.
    free(mesures);
    return 0;
}

