/* Les quatre exercices du TP 5, SANS saisie : les donnees de l'enonce sont
   ecrites dans le programme. Il sert a verifier ses propres resultats sans
   retaper huit mesures a chaque essai — et c'est le seul chemin par lequel
   une valeur annoncee ici peut etre recomparee automatiquement. */

int main(void)
{
    /* --- exercice 1 : le tableau fixe de l'enonce -------------------- */
    int mesures[8] = {12, 18, 7, 25, 14, 9, 21, 16};
    int *p = mesures;
    int somme1 = 0, maxi = *p, i;

    for (i = 0; i < 8; i++) { somme1 += *p; if (*p > maxi) maxi = *p; p++; }
    printf("ex.1  somme = %d, maximum = %d\n", somme1, maxi);

    /* --- exercice 2 : quatre valeurs saisies, ici en dur ------------- */
    {
        int n = 4, j, somme = 0;
        int *q = malloc(n * sizeof(int));
        int jeu[4] = {12, 18, 7, 25};
        if (q == NULL) return 1;
        for (j = 0; j < n; j++) q[j] = jeu[j];
        for (j = 0; j < n; j++) somme += q[j];
        printf("ex.2  somme = %d, moyenne = %.2f\n", somme, (float)somme / n);
        free(q);
    }

    /* --- exercice 3 : recherche de 25 dans cinq valeurs -------------- */
    {
        int n = 5, j, cherchee = 25, position = -1;
        int *q = malloc(n * sizeof(int));
        int jeu[5] = {12, 18, 7, 25, 14};
        if (q == NULL) return 1;
        for (j = 0; j < n; j++) q[j] = jeu[j];
        for (j = 0; j < n; j++) if (q[j] == cherchee) { position = j; break; }
        printf("ex.3  %d trouve a la position %d\n", cherchee, position);
        free(q);
    }

    /* --- exercice 4 : quatre mesures reelles, calloc ----------------- */
    {
        int n = 4, j;
        float jeu[4] = {18.5f, 21.25f, 17.0f, 19.75f};
        float somme = 0, mini, maxi4;
        float *m = calloc(n, sizeof(float));
        if (m == NULL) return 1;
        for (j = 0; j < n; j++) m[j] = jeu[j];
        mini = maxi4 = m[0];
        for (j = 0; j < n; j++) {
            somme += m[j];
            if (m[j] < mini)  mini  = m[j];
            if (m[j] > maxi4) maxi4 = m[j];
        }
        printf("ex.4  moyenne = %.2f, min = %.2f, max = %.2f\n",
               somme / n, mini, maxi4);
        free(m);
    }
    return 0;
}

