/* ========================================
 Exercice 3 :
 ========================================
Une entreprise possède 5 produits en stock, décrits par la structure Produit
(nom, prix, quantité).

struct Produit {
    char nom[30];
    float prix;
    int quantite;
};

Écrire un programme qui :
    1. Déclare un tableau de 5 produits.
    2. Permet de saisir les informations des 5 produits.
    3. Affiche les informations de tous les produits.
    4. Calcule et affiche la valeur totale du stock.
*/

#include <stdio.h>

#define N 5

struct Produit {
    char  nom[30];
    float prix;
    int   quantite;
};

int main(void)
{
    // 1. Déclare un tableau de 5 produits.
    struct Produit stock[N];
    float total = 0;
    int i;

    for (i = 0; i < N; i++) {
        // 2. Permet de saisir les informations des 5 produits.
        printf("Produit %d — nom      : ", i + 1);
        scanf("%29s", stock[i].nom);
        printf("Produit %d — prix     : ", i + 1);
        scanf("%f", &stock[i].prix);
        printf("Produit %d — quantite : ", i + 1);
        scanf("%d", &stock[i].quantite);
    }

    // 3. Affiche les informations de tous les produits.
    printf("\n%-14s %10s %6s %12s\n", "PRODUIT", "PRIX", "QTE", "VALEUR");
    for (i = 0; i < N; i++) {
        float valeur = stock[i].prix * stock[i].quantite;
        printf("%-14s %10.2f %6d %12.2f\n",
               stock[i].nom, stock[i].prix, stock[i].quantite, valeur);
        total += valeur;
    }
    // 4. Calcule et affiche la valeur totale du stock.
    printf("%-14s %29.2f\n", "TOTAL", total);
    return 0;
}

