struct Mesure { std::string machine; int ping; };

int main()
{
    std::vector<Mesure> m = {{"srv-web", 48}, {"srv-bdd", 12}, {"poste-12", 97}};

    std::sort(m.begin(), m.end(),
              [](const Mesure& a, const Mesure& b) { return a.ping < b.ping; });

    for (const Mesure& x : m) {
        std::cout << x.machine << " -> " << x.ping << " ms" << std::endl;
    }

    std::map<std::string, int> total;
    for (const Mesure& x : m) total[x.ping < 50 ? "rapide" : "lent"]++;

    for (const auto& paire : total) {
        std::cout << paire.first << " : " << paire.second << std::endl;
    }
    return 0;
}

