fichiers.script.js:
/* Le bonus du TP : « afficher le code hexadécimal de la couleur choisie ».
   « input » se déclenche PENDANT que l'on déplace le curseur de couleur ;
   « change » attendrait qu'on referme le sélecteur. Ici on veut voir le code
   bouger en même temps que la couleur, donc « input ». */
const couleur = document.querySelector("#couleur");
const hexa = document.querySelector("#hexa");

function afficher() {
    hexa.textContent = couleur.value;
    /* Et on montre la couleur sur l'étiquette elle-même : le texte blanc ou
       noir selon que le fond est sombre ou clair, pour rester lisible. */
    hexa.style.background = couleur.value;
    hexa.style.color = clair(couleur.value) ? "#000" : "#fff";
}

/* La luminance perçue : le vert compte plus que le rouge, et le bleu
   presque pas. C'est la formule des recommandations d'accessibilité. */
function clair(hex) {
    const r = parseInt(hex.slice(1, 3), 16);
    const v = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return (0.299 * r + 0.587 * v + 0.114 * b) > 140;
}

couleur.addEventListener("input", afficher);
afficher();

