.chapeau { margin-top: 0; font-size: 1.05rem; color: #6b6257; max-width: 38rem; }

/* « Organise le tout avec des sections » : chacune devient une carte. La
   règle est écrite une fois et vaut pour les quatre — et pour la cinquième
   qu'on ajoutera. */
section {
    margin: 1.6rem 0;
    padding: 1.2rem 1.4rem;
    background: white;
    border-radius: 12px;
    box-shadow: 0 1px 8px rgba(0, 0, 0, .07);
}

section h2 { margin-top: 0; color: #bc6c25; font-size: 1.3rem; }

a { color: #1b4965; font-weight: 600; }

.langages li, .etapes li { margin-bottom: .4rem; }

.duo { display: flex; flex-wrap: wrap; gap: 1rem; }
.duo img { border-radius: 8px; max-width: 100%; height: auto; }

.inscription p { margin: 0 0 .9rem; }

.inscription label { display: block; font-weight: 600; margin-bottom: .25rem; }

.inscription input, .inscription select, .inscription textarea {
    width: 100%;
    box-sizing: border-box;
    padding: .55rem .7rem;
    border: 1px solid #c9c0b2;
    border-radius: 8px;
    font: inherit;
}

.inscription button {
    padding: .65rem 1.4rem;
    border: 0;
    border-radius: 8px;
    background: #1b4965;
    color: white;
    font: inherit;
    font-weight: 600;
    cursor: pointer;
}

/* ═════════ a) les sélecteurs simples ═════════
   Par balise, par classe, par identifiant. Trois portées différentes :
   la balise touche tout, la classe un groupe, l'identifiant un seul. */
h1, h2 {
    font-family: Georgia, serif;
    color: #1b4965;
}

.services {
    list-style: none;
    padding: 0;
}

#contactForm {
    padding: 1.4rem 1.6rem;
    border: 1px solid #d6cfc2;
    border-radius: 12px;
    background: #fbf9f4;
}

/* ═════════ b) les sélecteurs COMBINÉS ═════════
   C'est le cœur du TP. Quatre façons de relier deux sélecteurs, et elles
   ne disent pas la même chose. */

/* 1. « A B » — DESCENDANT : un li quelque part dans .services, à
      n'importe quelle profondeur. */
ul.services li {
    padding: .7rem 1rem;
    margin-bottom: .5rem;
    border-left: 4px solid #bc6c25;
    background: white;
    border-radius: 0 8px 8px 0;
}

/* 2. « A B » encore, sur le formulaire : tous les input qu'il contient. */
form input {
    width: 100%;
    box-sizing: border-box;
    padding: .55rem .7rem;
    margin-bottom: .9rem;
    border: 1px solid #c9c0b2;
    border-radius: 8px;
    font: inherit;
}

/* 3. « A + B » — FRÈRE IMMÉDIAT : l'input qui suit DIRECTEMENT un label.
      Si on glissait un <span> entre les deux, la règle ne s'appliquerait
      plus. C'est là toute la différence avec « ~ ». */
label + input {
    border-color: #1b4965;
}

/* 4. « A > B » — ENFANT DIRECT : le bouton enfant du formulaire.
      Un bouton enfoui dans un <div> à l'intérieur du formulaire ne serait
      PAS touché. « form button » l'aurait touché. */
form > button {
    padding: .7rem 1.6rem;
    border: 0;
    border-radius: 8px;
    background: #1b4965;
    color: white;
    font: inherit;
    font-weight: 600;
    cursor: pointer;
    transition: background .15s;
}

/* ═════════ c) le style, et le survol ═════════ */
body {
    font-family: system-ui, sans-serif;
    margin: 0 auto;
    padding: 2rem 1.2rem 4rem;
    max-width: 36rem;
    background: #f4f1ea;
    color: #2d2a26;
    line-height: 1.6;
}

label {
    display: block;
    font-weight: 600;
    margin-bottom: .25rem;
}

select, textarea {
    width: 100%;
    box-sizing: border-box;
    padding: .55rem .7rem;
    margin-bottom: .9rem;
    border: 1px solid #c9c0b2;
    border-radius: 8px;
    font: inherit;
}

form > button:hover { background: #bc6c25; }

/* Le survol se double d'un état de focus : au clavier, il n'y a pas de
   souris, donc pas de :hover. Les deux vont ensemble, toujours. */
form > button:focus-visible { outline: 3px solid #bc6c25; outline-offset: 2px; }

body {
    font-family: system-ui, sans-serif;
    margin: 0;
    padding: 2rem 1.2rem 4rem;
    background: #f4f1ea;
    color: #2d2a26;
    line-height: 1.6;
}

h1 { text-align: center; color: #1b4965; }

/* ═════════ 2d) la mise en page : Flexbox ═════════
   « côte à côte sur grand écran » — donc en colonne par défaut, et côte à
   côte seulement quand il y a la place. On écrit le petit écran d'abord :
   c'est plus simple à lire, et c'est le cas le plus fréquent. */
.deux-colonnes {
    display: flex;
    flex-direction: column;
    gap: 1.6rem;
    max-width: 62rem;
    margin: 1.8rem auto 0;
}

@media (min-width: 52rem) {
    .deux-colonnes { flex-direction: row; align-items: flex-start; }
    /* « flex: 1 » sur les deux : elles se partagent la largeur à parts
       égales. « flex: 1 1 0 » en entier, dont le « 0 » est ce qui empêche
       le contenu de décider de la largeur. */
    .colonne { flex: 1 1 0; }
}

.colonne {
    padding: 1.2rem 1.4rem;
    background: white;
    border-radius: 12px;
    box-shadow: 0 1px 8px rgba(0, 0, 0, .07);
}

/* ═════════ 2c) pseudo-éléments ═════════
   « ::before » fabrique un contenu qui n'est pas dans le HTML. Il sert aux
   DÉCORATIONS — jamais à du texte qui compte : un lecteur d'écran peut ne
   pas le lire, et on ne peut pas le sélectionner à la souris. */
h2 {
    margin-top: 0;
    color: #bc6c25;
    font-size: 1.25rem;
}

h2::before {
    content: "▚ ";
    color: #d8c6a8;
}

.event-list > li::marker { color: #bc6c25; font-weight: 700; }

/* Les sous-listes : une petite flèche en guise de puce. */
.event-list ul { list-style: none; padding-left: 1.2rem; }

.event-list ul li::before {
    content: "→ ";
    color: #8a8178;
}

/* ═════════ 2c) pseudo-classes ═════════ */
.event-list ul li {
    padding: .2rem .4rem;
    border-radius: 6px;
    transition: background .12s;
}

.event-list ul li:hover { background: #fdefe2; }

label { display: block; font-weight: 600; margin: .6rem 0 .25rem; }

fieldset p label { display: inline; font-weight: normal; margin: 0 0 0 .4rem; }

input[type="text"], input[type="email"], select, textarea {
    width: 100%;
    box-sizing: border-box;
    padding: .55rem .7rem;
    border: 1px solid #c9c0b2;
    border-radius: 8px;
    font: inherit;
}

/* « :focus » dit où l'on est au clavier. Le supprimer pour faire « propre »
   rend le formulaire inutilisable sans souris : c'est l'erreur la plus
   courante du CSS. */
input:focus, select:focus, textarea:focus {
    outline: 2px solid #1b4965;
    outline-offset: 1px;
    background: #f7fbfd;
}

fieldset {
    margin: 1rem 0;
    padding: .6rem 1rem .1rem;
    border: 1px solid #e0d9cc;
    border-radius: 10px;
}

fieldset p { margin: 0 0 .4rem; }

legend { padding: 0 .4rem; font-weight: 700; color: #1b4965; font-size: .95rem; }

button {
    margin-top: 1rem;
    padding: .7rem 1.6rem;
    border: 0;
    border-radius: 8px;
    background: #1b4965;
    color: white;
    font: inherit;
    font-weight: 600;
    cursor: pointer;
    transition: transform .12s, background .15s;
}

button:hover { background: #bc6c25; transform: translateY(-1px); }
button:active { transform: none; }

/* Quelqu'un qui a demandé moins d'animations à son système n'en veut pas
   ici non plus. Deux lignes, et c'est réglé. */
@media (prefers-reduced-motion: reduce) {
    * { transition: none !important; }
}

* { box-sizing: border-box; }

body {
    margin: 0;
    font-family: system-ui, sans-serif;
    background: #f4f1ea;
    color: #2d2a26;
    /* Le corps aussi est un conteneur flex, en colonne : c'est ce qui permet
       au footer de rester en bas même quand la page est courte. */
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

/* ═════════ 1. LE HEADER ═════════
   Trois éléments, un à gauche, un au milieu, un à droite.
   « space-between » met tout l'espace restant ENTRE eux : le premier
   touche le bord gauche, le dernier le bord droit. C'est exactement ce
   qu'on veut, et ça ne demande aucune largeur. */
header {
    display: flex;
    justify-content: space-between;
    align-items: center;            /* le centrage vertical demandé */
    gap: 1rem;
    padding: 0 1.4rem;
    min-height: 64px;
    background: #1b4965;
    color: #f0f4f7;
}

.logo { font-weight: 800; font-size: 1.2rem; letter-spacing: .02em; }

header nav { display: flex; gap: 1.4rem; }

header nav a {
    color: #cfe0ec;
    text-decoration: none;
    font-weight: 600;
}

header nav a:hover { color: white; text-decoration: underline; }

.utilisateur {
    padding: .35rem .8rem;
    border: 1px solid #4a7694;
    border-radius: 999px;
    font-size: .85rem;
}

/* ═════════ 2. LA SECTION PRINCIPALE ═════════
   Un conteneur flex HORIZONTAL : la barre latérale et le contenu.
   « flex: 1 » sur le conteneur lui-même le fait occuper la hauteur
   restante entre le header et le footer. */
.container {
    display: flex;
    flex: 1;
    align-items: stretch;
}

/* A. la barre latérale — en COLONNE, largeur fixe */
.sidebar {
    display: flex;
    flex-direction: column;
    gap: .4rem;
    flex: 0 0 220px;        /* ne grandit pas, ne rétrécit pas, 220 px */
    padding: 1.2rem 1rem;
    background: #e4ded2;
}

.sidebar a {
    padding: .6rem .8rem;
    border-radius: 8px;
    color: #4a4238;
    text-decoration: none;
    font-weight: 600;
}

.sidebar a:hover { background: #d4cbba; color: #1b4965; }

/* B. le contenu — il prend TOUT le reste */
.content {
    flex: 1;
    padding: 1.6rem 2rem;
    background: #fbf9f4;
    line-height: 1.65;
}

.content h1 { margin-top: 0; color: #1b4965; font-size: 1.6rem; }

/* ═════════ 3. LE FOOTER ═════════
   Flexbox pour centrer dans les DEUX sens, d'un coup : « justify-content »
   pour l'horizontale, « align-items » pour la verticale. C'est le centrage
   le plus court que le CSS sache écrire. */
footer {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 60px;
    background: #1b4965;
    color: #cfe0ec;
    font-size: .9rem;
}

/* Sur un téléphone, la barre latérale passe au-dessus du contenu :
   220 px de côté sur un écran de 375, il ne resterait rien. */
@media (max-width: 46rem) {
    .container { flex-direction: column; }
    .sidebar { flex-basis: auto; flex-direction: row; flex-wrap: wrap; }
    header { flex-wrap: wrap; padding: .8rem 1rem; }
}

* { box-sizing: border-box; }

body {
    margin: 0;
    padding: 2rem 1.4rem 4rem;
    font-family: system-ui, sans-serif;
    background: #f4f1ea;
    color: #2d2a26;
    line-height: 1.6;
}

h1 { text-align: center; color: #1b4965; margin-bottom: 1.8rem; }

/* ═════════ CSS GRID ═════════
   Pourquoi Grid et pas Flexbox : Flexbox range sur UNE ligne et laisse le
   contenu décider des largeurs. Grid pose une trame À L'AVANCE — trois
   colonnes de largeur égale — et les cartes s'y rangent. Les colonnes sont
   alignées même si une carte a trois lignes de texte et sa voisine une.

   « 1fr » = une part de la place disponible. Trois parts égales.
   « minmax(0, 1fr) » plutôt que « 1fr » seul : sans le 0, un contenu long
   (une URL, un mot très long) peut élargir sa colonne et casser l'égalité. */
.grid-projects {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 1.4rem;
    max-width: 64rem;
    margin: 0 auto;
}

.card {
    display: flex;              /* pour que la vignette soit en haut */
    flex-direction: column;
    overflow: hidden;
    background: white;
    border-radius: 14px;
    box-shadow: 0 1px 6px rgba(0, 0, 0, .08);
    transition: transform .16s, box-shadow .16s;
}

/* L'effet au survol : la carte se SOULÈVE — elle monte un peu, et son
   ombre grandit. Les deux ensemble, sinon ça ne ressemble à rien. */
.card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 22px rgba(0, 0, 0, .14);
}

/* « L'image » est ici un dégradé : le TP l'autorise, et une page qui ne
   demande aucun fichier extérieur se charge toujours. */
.vignette { height: 120px; }
.v1 { background: linear-gradient(135deg, #1b4965, #468faf); }
.v2 { background: linear-gradient(135deg, #5c4b8a, #9a86c4); }
.v3 { background: linear-gradient(135deg, #1d5440, #5aa17f); }
.v4 { background: linear-gradient(135deg, #8a4b12, #d79a5b); }
.v5 { background: linear-gradient(135deg, #7a3550, #c47a93); }
.v6 { background: linear-gradient(135deg, #4a4238, #8d8275); }

.card h3 { margin: 1rem 1.1rem .3rem; color: #1b4965; font-size: 1.1rem; }
.card p  { margin: 0 1.1rem 1.2rem; font-size: .92rem; color: #5a5249; }

/* Trois colonnes fixes ne tiennent pas sur un téléphone. Deux paliers, et
   la trame se refait toute seule. */
@media (max-width: 54rem) { .grid-projects { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 34rem) { .grid-projects { grid-template-columns: 1fr; } }

@media (prefers-reduced-motion: reduce) {
    .card { transition: none; }
    .card:hover { transform: none; }
}

/* ═══════════════════════════════════════════════════════════════════
   LA GRILLE, ÉCRITE À LA MAIN
   Le sujet s'appuyait sur une bibliothèque d'habillage. Les classes
   gardent leurs noms d'origine — « row », « col-md-6 », « btn »,
   « mb-3 », « w-100 » — pour que le HTML du TP reste valable ; ce
   fichier montre ce qu'il y a derrière.
   ═══════════════════════════════════════════════════════════════════ */

* { box-sizing: border-box; }

body {
    margin: 0;
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    background: #f7f6f3;
    color: #22252a;
    line-height: 1.6;
}

/* « container » : une largeur maximale, et centré. Rien de plus. */
.container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 1rem 3rem;
}

/* « row » / « col » : une rangée est un conteneur flex qui revient à la
   ligne ; une colonne prend toute la largeur PAR DÉFAUT. C'est l'ordre
   « petit écran d'abord » : on part du téléphone, et on élargit ensuite. */
.row {
    display: flex;
    flex-wrap: wrap;
    margin: 0 -.75rem;       /* la gouttière : annulée aux bords */
}

.col {
    flex: 0 0 100%;
    max-width: 100%;
    padding: 0 .75rem 1.5rem;
}

/* Le palier « md » — à partir de 768 px, comme dans la bibliothèque
   d'origine. Douze colonnes : la moitié fait 50 %, le tiers 33,333 %,
   le quart 25 %. C'est toute l'arithmétique du système. */
@media (min-width: 768px) {
    .col-md-3 { flex: 0 0 25%;        max-width: 25%; }
    .col-md-4 { flex: 0 0 33.333333%; max-width: 33.333333%; }
    .col-md-6 { flex: 0 0 50%;        max-width: 50%; }
}

/* Les utilitaires, un par ligne : c'est leur principe. */
.text-center    { text-align: center; }
.text-secondary { color: #6b7280; }
.text-white     { color: #fff; }
.bg-dark        { background: #1f2328; }
.py-3           { padding-top: 1rem; padding-bottom: 1rem; }
.mb-3           { margin-bottom: 1rem; }
.w-100          { width: 100%; }

/* ═════════ L'en-tête ═════════ */
.entete {
    padding: 3.4rem 1.2rem 3rem;
    background: linear-gradient(160deg, #11314a, #1b4965 60%, #2e6b8f);
    color: #eaf2f7;
}

.entete h1 {
    margin: 0 0 .3rem;
    font-size: clamp(1.9rem, 6vw, 3rem);
    font-weight: 800;
    letter-spacing: -.02em;
    /* L'ombre du texte demandée par le sujet : discrète, sinon elle salit. */
    text-shadow: 0 2px 12px rgba(0, 0, 0, .35);
}

.entete .text-secondary { color: #a9c4d4; margin: 0 0 1.6rem; }

/* ═════════ Les boutons ═════════ */
.btn {
    display: inline-block;
    padding: .65rem 1.5rem;
    border: 0;
    border-radius: 8px;
    font: inherit;
    font-weight: 600;
    text-decoration: none;
    cursor: pointer;
    transition: background .15s, transform .12s;
}

.btn-success { background: #1d7a4f; color: #fff; }
.btn-success:hover { background: #166240; transform: translateY(-1px); }
.btn-primary { background: #1b4965; color: #fff; }
.btn-primary:hover { background: #142f42; }
.btn:focus-visible { outline: 3px solid #e8a04c; outline-offset: 2px; }

/* ═════════ Les sections ═════════ */
