/* ═════════ MOBILE PAR DÉFAUT ═════════
   Aucune media query ici : ce sont les règles de base. Écrire le petit
   écran d'abord, puis AJOUTER avec « min-width », c'est la méthode
   « mobile first ». L'inverse (« max-width » partout) oblige à tout
   défaire à chaque palier. */
body {
    margin: 0;
    padding: 1.5rem 1rem;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-family: system-ui, sans-serif;
    background: #eceae5;              /* fond gris clair */
    color: #2d2a26;
}

.carte {
    display: flex;
    flex-direction: column;           /* en colonne : centrée */
    align-items: center;
    gap: .9rem;
    width: 100%;
    max-width: 18rem;
    padding: 1.6rem 1.4rem;
    background: white;
    border-radius: 16px;              /* bordures arrondies */
    box-shadow: 0 2px 12px rgba(0, 0, 0, .12);   /* ombre légère */
    text-align: center;
}

/* La photo circulaire, optionnelle dans le sujet. Un dégradé plutôt qu'un
   fichier : rien à charger. */
.photo {
    width: 88px;
    height: 88px;
    border-radius: 50%;
    flex: 0 0 auto;
    background: linear-gradient(135deg, #1b4965, #6ba3c0);
}

.infos { min-width: 0; }

.nom     { margin: 0 0 .2rem; font-size: 16px; color: #1b4965; }
.metier  { margin: 0 0 .6rem; font-size: 14px; color: #6b6257; font-weight: 600; }
.contact { margin: .15rem 0;  font-size: 14px; color: #4a4238; }

.astuce {
    margin-top: 1.8rem;
    max-width: 26rem;
    font-size: .85rem;
    color: #6b6257;
    text-align: center;
}

/* ═════════ TABLETTE — à partir de 768 px ═════════ */
@media (min-width: 768px) {
    .carte { max-width: 24rem; padding: 2rem 1.8rem; }
    .nom     { font-size: 18px; }
    .metier  { font-size: 16px; }
    .contact { font-size: 16px; }
}

/* ═════════ ORDINATEUR — à partir de 1024 px ═════════ */
@media (min-width: 1024px) {
    .carte { max-width: 30rem; padding: 2.4rem 2.2rem; }
    .nom     { font-size: 20px; }
    .metier  { font-size: 18px; }
    .contact { font-size: 18px; }
    .photo   { width: 104px; height: 104px; }
}

/* ═════════ ORIENTATION PAYSAGE — large ET couché ═════════
   Deux conditions avec « and » : les deux doivent être vraies. Sans le
   « min-width », un téléphone couché déclencherait la règle alors qu'il
   n'a pas la largeur pour une carte en ligne. */
@media (min-width: 768px) and (orientation: landscape) {
    body { background: #dcebf5; }     /* fond bleu clair */
    .carte {
        flex-direction: row;          /* nom à gauche, infos à droite */
        align-items: center;
        text-align: left;
        gap: 1.4rem;
        max-width: 34rem;
    }
}

