/* ═════════ MOBILE PAR DÉFAUT ═════════ */
body {
    margin: 0;
    padding: 1.6rem 1rem 3rem;
    font-family: system-ui, sans-serif;
    background: #f6f4ef;              /* fond clair */
    color: #2d2a26;
    line-height: 1.6;
}

h1 {
    margin: 0 0 1.2rem;
    font-size: 1.6rem;
    color: #1b4965;
}

/* Le formulaire est un conteneur flex en colonne : chaque champ sur sa
   ligne, et le « gap » remplace les marges qu'il faudrait sinon régler
   un par un. */
form {
    display: flex;
    flex-direction: column;
    gap: .2rem;
}

label { font-weight: 600; margin-top: .7rem; font-size: .95rem; }

input, textarea {
    width: 100%;
    padding: .7rem .8rem;             /* un padding confortable au doigt */
    border: 1px solid #c9c0b2;        /* des bordures simples */
    border-radius: 8px;
    font: inherit;
    background: white;
}

input:focus, textarea:focus {
    outline: 2px solid #1b4965;
    outline-offset: 1px;
}

button {
    width: 100%;                      /* bouton pleine largeur */
    margin-top: 1.2rem;
    padding: .85rem 1rem;
    border: 0;
    border-radius: 10px;
    background: #1b4965;
    color: white;
    font: inherit;
    font-size: 1.05rem;
    font-weight: 600;
    cursor: pointer;
}

button:hover { background: #142f42; }

.astuce {
    margin-top: 1.6rem;
    font-size: .85rem;
    color: #6b6257;
}

/* ═════════ TABLETTE — à partir de 768 px ═════════ */
@media (min-width: 768px) {
    body { padding-top: 2.6rem; }

    h1, form, .astuce {
        max-width: 32rem;             /* centré, largeur limitée */
        margin-left: auto;
        margin-right: auto;
    }

    label, input, textarea { font-size: 1rem; }

    /* Le bouton reprend sa taille et s'aligne à droite : « align-self »
       ne vaut que pour LUI, les champs gardent leur pleine largeur. */
    button {
        width: auto;
        align-self: flex-end;
        padding: .7rem 1.8rem;
        font-size: 1rem;
    }
}

/* ═════════ ORDINATEUR — à partir de 1024 px ═════════ */
@media (min-width: 1024px) {
    h1, form, .astuce { max-width: 40rem; }
    h1 { font-size: 2rem; }
    label, input, textarea { font-size: 1.05rem; }
    input, textarea { padding: .8rem .9rem; }
}

/* ═════════ PAYSAGE — large ET couché ═════════ */
@media (min-width: 768px) and (orientation: landscape) {
    form {
        padding: 1.6rem;
        border-radius: 14px;
        background: #fffdf8;          /* le fond du formulaire change */
        box-shadow: 0 8px 28px rgba(0, 0, 0, .16);   /* ombre plus visible */
    }
}

* { box-sizing: border-box; }

:root {
    --fond: #f5f2ec;
    --encre: #262a2e;
    --douce: #5f6670;
    --accent: #1b4965;
    --chaud: #c06014;
    --carte: #ffffff;
}

body {
    margin: 0;
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    background: var(--fond);
    color: var(--encre);
    line-height: 1.65;
}

/* ═════════ 1. L'EN-TÊTE, en Flexbox ═════════
   Le nom à gauche, le menu à droite, l'espace réparti entre les deux. */
header {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding: 1.1rem clamp(1rem, 4vw, 3rem);
    background: var(--accent);
    color: #e9f1f6;
    /* L'en-tête suit le défilement : sur un CV d'une seule page, le menu
       doit rester atteignable. */
    position: sticky;
    top: 0;
    z-index: 10;
}

.identite { display: flex; align-items: center; gap: .8rem; }

.avatar {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: linear-gradient(135deg, #e8a04c, #c06014);
    flex: 0 0 auto;
}

.moi { font-weight: 700; font-size: 1.05rem; }

header nav { display: flex; flex-wrap: wrap; gap: 1.2rem; }

header nav a {
    color: #bdd5e3;
    text-decoration: none;
    font-weight: 600;
    font-size: .95rem;
    padding: .2rem 0;
    border-bottom: 2px solid transparent;
}

header nav a:hover { color: white; border-bottom-color: #e8a04c; }

main {
    max-width: 62rem;
    margin: 0 auto;
    padding: 0 clamp(1rem, 4vw, 3rem) 3rem;
}

section { padding-top: 2.6rem; }

/* « scroll-margin-top » : sans elle, un clic dans le menu amène le titre
   SOUS l'en-tête collé, et on croit que le lien est cassé. */
section { scroll-margin-top: 5rem; }

h2 {
    margin: 0 0 1.2rem;
    font-size: 1.5rem;
    color: var(--accent);
}

h2::after {
    content: "";
    display: block;
    width: 2.6rem;
    height: 3px;
    margin-top: .45rem;
    background: var(--chaud);
    border-radius: 2px;
}

/* ═════════ 2. « À PROPOS » — photo et texte côte à côte ═════════ */
.apropos-bloc {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: 1.6rem;
}

.photo {
    width: 140px;
    height: 140px;
    flex: 0 0 auto;
    border-radius: 14px;
    background: linear-gradient(135deg, var(--accent), #74a8c4);
    box-shadow: 0 4px 16px rgba(27, 73, 101, .22);
}

.apropos-bloc > div { flex: 1 1 18rem; min-width: 0; }
.apropos-bloc p:first-child { margin-top: 0; }

/* ═════════ 3. LES COMPÉTENCES, en CSS Grid ═════════
   « auto-fit » + « minmax » : le nombre de colonnes se décide tout seul
   selon la place. Pas un seul palier à écrire — la grille compte à notre
   place. C'est ce que Grid fait de mieux. */
.grille-competences {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(15rem, 100%), 1fr));
    gap: 1rem;
}

.competence {
    padding: 1.1rem 1.2rem;
    background: var(--carte);
    border: 1px solid #e5e0d7;
    border-left: 4px solid var(--chaud);
    border-radius: 0 12px 12px 0;
    transition: transform .15s, box-shadow .15s;
}

.competence:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 20px rgba(0, 0, 0, .1);
}

.competence h3 { margin: 0 0 .3rem; font-size: 1.02rem; color: var(--accent); }
.competence p  { margin: 0; font-size: .92rem; color: var(--douce); }

/* ═════════ 4. LES EXPÉRIENCES ═════════
   Verticales par défaut, côte à côte s'il y a la place : le sujet laisse
   le choix, et « auto-fit » tient les deux cas d'un seul geste. */
.grille-exp {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(20rem, 100%), 1fr));
    gap: 1.1rem;
}

.exp {
    padding: 1.2rem 1.3rem;
    background: var(--carte);
    border: 1px solid #e5e0d7;
    border-radius: 12px;
}

.exp h3 { margin: 0 0 .15rem; font-size: 1.05rem; color: var(--accent); }

.periode {
    margin: 0 0 .6rem;
    font-size: .85rem;
    font-weight: 700;
    letter-spacing: .03em;
    text-transform: uppercase;
    color: var(--chaud);
}

.exp p:last-child { margin: 0; color: var(--douce); }

/* ═════════ 5. LE PIED DE PAGE ═════════
   Centré dans les deux sens, et de la même couleur que l'en-tête. */
footer {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: .2rem;
    min-height: 110px;
    padding: 1.4rem 1rem;
    background: var(--accent);
    color: #cfe0ec;
    text-align: center;
}

footer p { margin: 0; }
footer a { color: #e8a04c; }
footer .petit { font-size: .85rem; color: #9ab6c8; }

@media (prefers-reduced-motion: reduce) {
    .competence { transition: none; }
    .competence:hover { transform: none; }
}

@media print {
    header { position: static; }
    .competence:hover, .exp { box-shadow: none; }
}

