/* TP 1, exercice 1 — deux températures, la plus élevée.

   Le piège de l'exercice n'est pas la comparaison, c'est le TYPE :
   prompt() rend toujours du TEXTE. Comparer "9" et "10" comme du texte
   donne "9" > "10" — vrai, parce que le caractère 9 vient après le 1.
   Number() est donc obligatoire, pas décoratif. */

const t1 = Number(prompt("Première température (°C) :"));
const t2 = Number(prompt("Deuxième température (°C) :"));

/* Number("abc") ne lève pas d'erreur : il rend NaN. Et NaN n'est égal à
   rien, pas même à lui-même — d'où Number.isNaN() pour le détecter. */
if (Number.isNaN(t1) || Number.isNaN(t2)) {
    console.log("Il faut deux nombres.");
} else if (t1 === t2) {
    console.log("Les deux températures sont identiques : " + t1 + " °C");
} else {
    const plus = Math.max(t1, t2);
    console.log("La plus élevée est " + plus + " °C");
}

/* TP 1, exercice 2 — nombre premier.

   Un nombre premier est un entier > 1 dont les seuls diviseurs sont 1 et
   lui-même.

   On ne teste PAS tous les nombres jusqu'à n : si n a un diviseur d plus
   grand que sa racine carrée, alors n / d est un diviseur PLUS PETIT que
   la racine — et on l'aurait déjà trouvé. Chercher jusqu'à √n suffit
   donc, et c'est bien plus rapide : pour 1 000 003, trente-deux tours au
   lieu d'un million. */

const n = Number(prompt("Un nombre entier :"));

function estPremier(n) {
    if (!Number.isInteger(n) || n <= 1) return false;   // 0, 1, négatifs : non
    if (n <= 3) return true;                            // 2 et 3 : oui
    if (n % 2 === 0) return false;                      // tous les pairs sauf 2

    /* On ne teste plus que les impairs : 3, 5, 7, 9… */
    for (let d = 3; d * d <= n; d += 2) {
        if (n % d === 0) return false;
    }
    return true;
}

if (Number.isNaN(n)) {
    console.log("Ce n'est pas un nombre.");
} else if (estPremier(n)) {
    console.log("Le nombre " + n + " est premier");
} else {
    console.log("Le nombre " + n + " n'est pas premier");
}

/* Pour voir la fonction à l'œuvre sans rien taper : */
console.log("");
console.log("Vérification sur les vingt premiers entiers :");
let premiers = [];
for (let i = 1; i <= 20; i++) {
    if (estPremier(i)) premiers.push(i);
}
console.log(premiers.join(", "));

/* TP 1, exercice 3 — vérifier un nom d'utilisateur et un mot de passe.

   Les valeurs attendues par le sujet : admin / 2024. */

const nom = prompt("Nom d'utilisateur :");
const mdp = prompt("Mot de passe :");

/* « && » : les DEUX doivent être vraies. Il est « court-circuité » — si la
   première est fausse, la seconde n'est même pas évaluée. */
if (nom === "admin" && mdp === "2024") {
    console.log("Bienvenue sur la plateforme");
} else {
    /* Un seul message pour les deux cas. Dire « mot de passe incorrect »
       révélerait que le nom, lui, est bon : c'est une information offerte
       à qui essaie des comptes au hasard. */
    console.log("Identifiants incorrects");
}

console.log("");
console.log("--- Ce que cet exercice n'est pas ---");
console.log("Un mot de passe écrit dans le code est lisible par tous :");
console.log("le JavaScript d'une page est téléchargé par le navigateur.");
console.log("En vrai, le mot de passe ne quitte pas le serveur, et ce");
console.log("n'est pas lui qui y est stocké mais son empreinte (hachage).");

/* TP 1, exercice 4 — l'accès.

   Les règles du sujet :
     · âge ≥ 18 ET statut « employé »   → autorisé
     · âge ≥ 21 ET statut « étudiant »  → autorisé
     · tout le reste                    → refusé */

const age = Number(prompt("Votre âge :"));
const statut = (prompt("Votre statut (étudiant / employé) :") || "")
                   .trim().toLowerCase();

/* Les deux règles s'écrivent telles quelles, reliées par « || » (OU).
   Les parenthèses ne sont pas obligatoires — « && » est prioritaire sur
   « || » — mais elles rendent la ligne lisible, et une ligne de condition
   qu'on doit déchiffrer est une ligne qu'on finira par casser. */
const autorise = (age >= 18 && statut === "employé")
              || (age >= 21 && statut === "étudiant");

console.log(autorise ? "Accès autorisé" : "Accès refusé");

/* toLowerCase() et trim() sur la saisie : « Employé », « EMPLOYÉ  » et
   « employé » sont la même réponse pour un humain. Sans eux, l'exercice
   refuse quelqu'un qui a seulement appuyé sur Maj. */

console.log("");
console.log("--- La table complète ---");
const cas = [[17, "employé"], [18, "employé"], [20, "étudiant"],
             [21, "étudiant"], [25, "autre"]];
for (const [a, s] of cas) {
    const ok = (a >= 18 && s === "employé") || (a >= 21 && s === "étudiant");
    console.log(a + " ans, " + s + " → " + (ok ? "autorisé" : "refusé"));
}

/* TP 2 — l'outil de supervision réseau.
   Les dix questions du sujet, dans l'ordre, chacune annoncée.

   Le fil conducteur : la MÊME tâche écrite de cinq façons (déclaration,
   variable, anonyme, forEach, fléchée). Ce n'est pas de la répétition —
   c'est la question « laquelle choisir, et pourquoi ». */

let postes = [
    { nom: "PC-01", ip: "192.168.0.10", enLigne: true,  ram: 8  },
    { nom: "PC-02", ip: "192.168.0.11", enLigne: false, ram: 4  },
    { nom: "PC-03", ip: "192.168.0.12", enLigne: true,  ram: 16 },
    { nom: "PC-04", ip: "192.168.0.13", enLigne: false, ram: 2  }
];

/* ── 1. une fonction sans paramètre ── */
function afficherTitre() {
    console.log("=== OUTIL DE SUPERVISION RÉSEAU ===");
}
afficherTitre();

/* ── 2. deux paramètres ── */
function afficherPoste(nom, ip) {
    console.log("Poste : " + nom + " | IP : " + ip);
}
afficherPoste(postes[0].nom, postes[0].ip);

/* ── 3. une fonction qui RETOURNE. « return » rend une valeur à
      l'appelant ; console.log() l'affiche et ne rend rien. Les deux sont
      souvent confondus, et c'est la confusion la plus coûteuse du TP. ── */
function estEnLigne(poste) {
    return poste.enLigne;
}
console.log("");
console.log("postes[1] en ligne ? " + estEnLigne(postes[1]));

/* ── 4. parcourir avec une boucle ── */
function listerPostes(liste) {
    console.log("");
    for (let i = 0; i < liste.length; i++) {
        console.log("Nom : " + liste[i].nom + " | IP : " + liste[i].ip);
    }
}
listerPostes(postes);

/* ── 5. compter, et retourner le compte ── */
function compterHorsLigne(liste) {
    let n = 0;
    for (const p of liste) {
        if (!p.enLigne) n++;
    }
    return n;
}
console.log("");
console.log("Postes hors ligne : " + compterHorsLigne(postes));

/* ── 6. une fonction dans une VARIABLE (expression de fonction).
      Différence avec la déclaration du point 1 : celle-ci n'existe
      qu'à partir de cette ligne. Une fonction déclarée, elle, est
      utilisable même au-dessus de sa définition. ── */
const afficherIp = function (ip) {
    console.log("IP : " + ip);
};
console.log("");
for (const p of postes) {
    afficherIp(p.ip);
}

/* ── 7. forEach avec une fonction ANONYME : elle n'a pas de nom parce
      qu'on ne l'appellera jamais ailleurs. ── */
console.log("");
postes.forEach(function (p) {
    console.log("Nom du poste : " + p.nom);
});

/* ── 8. la même chose, en fonction FLÉCHÉE. Plus courte, et c'est tout
      ce qui change ici. (Sa vraie différence — le « this » — ne se voit
      pas dans cet exercice.) ── */
console.log("");
postes.forEach((p) => console.log("Nom du poste : " + p.nom));

/* ── 9. une fléchée qui retourne. Pas d'accolades, donc pas besoin
      d'écrire « return » : la valeur de l'expression EST le retour. ── */
const etatRam = (ram) => (ram >= 8 ? "Suffisante" : "Insuffisante");
console.log("");
postes.forEach((p) => console.log(p.nom + " — RAM " + p.ram + " Go : " + etatRam(p.ram)));

/* ── 10. une fonction qui RÉUTILISE celle du point 3.
      C'est le point le plus important du TP : la règle « est-il en
      ligne ? » est écrite une seule fois. Le jour où elle change, on la
      change à un seul endroit. ── */
function annoncer(poste) {
    console.log(poste.nom + (estEnLigne(poste) ? " est en ligne" : " est hors ligne"));
}
console.log("");
postes.forEach(annoncer);

/* Révision — examen blanc, exercice 1 : le laboratoire.

   Même squelette que le TP 2, autres données : c'est voulu. Si on a
   compris le TP 2, cet exercice se fait en recopiant la structure. */

let echantillons = [
    { id: 101, nom: "Acide Sulfurique", pH: 1.2, inflammable: false },
    { id: 102, nom: "Éthanol",          pH: 7,   inflammable: true  },
    { id: 103, nom: "Sodium",           pH: 13,  inflammable: true  },
    { id: 104, nom: "Eau distillée",    pH: 7,   inflammable: false }
];

/* ── 1. l'état acide / base d'un seuil saisi ── */
const seuil = Number(prompt("Un seuil de pH (0 à 14) :"));

if (Number.isNaN(seuil) || seuil < 0 || seuil > 14) {
    console.log("Un pH va de 0 à 14.");
} else if (seuil <= 3) {
    console.log("pH " + seuil + " → Acide fort");
} else if (seuil >= 11) {
    console.log("pH " + seuil + " → Basique");
} else if (Math.abs(seuil - 7) < 0.5) {
    /* « pH ≈ 7 » : on ne teste JAMAIS l'égalité d'un décimal. 6.9999999
       n'est pas 7 pour la machine. On teste un écart. */
    console.log("pH " + seuil + " → Neutre");
} else {
    console.log("pH " + seuil + " → ni acide fort, ni neutre, ni basique");
}

/* ── 2. le titre ── */
function afficherTitre() {
    console.log("");
    console.log("=== GESTION DU LABORATOIRE ===");
}
afficherTitre();

/* ── 3. afficher un échantillon ── */
function afficherEchantillon(nom, pH) {
    console.log("Échantillon : " + nom + " | pH : " + pH);
}
afficherEchantillon(echantillons[1].nom, echantillons[1].pH);

/* ── 4. l'inflammabilité ── */
function estInflammable(e) {
    return e.inflammable;
}
console.log("echantillons[2] inflammable ? " + estInflammable(echantillons[2]));

/* ── 5. parcourir, et compter ── */
console.log("");
let nbInflammables = 0;
for (const e of echantillons) {
    console.log("ID " + e.id + " | Inflammable : " + e.inflammable);
    if (estInflammable(e)) nbInflammables++;
}
console.log("Total inflammables : " + nbInflammables);

/* ── 6. l'état de sécurité, en fonction fléchée ── */
const etatSecurite = (e) =>
    (e.inflammable || e.pH <= 2 || e.pH >= 12) ? "Danger" : "Sûr";

console.log("");
echantillons.forEach((e) => console.log(e.nom + " → " + etatSecurite(e)));

/* ── 7. la moyenne des pH ──
   reduce() additionne en un passage : il part de 0 et ajoute chaque pH.
   Écrit avec une boucle, ce serait trois lignes de plus et le même
   résultat — les deux sont justes. */
function pHMoyen(liste) {
    const somme = liste.reduce((total, e) => total + e.pH, 0);
    return somme / liste.length;
}
console.log("");
console.log("pH moyen : " + pHMoyen(echantillons).toFixed(2));

/* Révision — examen blanc, exercice 2 : les athlètes.

   La différence avec l'exercice 1 : chaque athlète est un TABLEAU, pas
   un objet. On accède donc par POSITION — athlete[0] est le nom — et
   plus par nom de champ. C'est moins lisible, et c'est exactement ce que
   l'exercice fait sentir. */

let athletes = [
    ["Alice",   23, 15.2, true ],
    ["Bob",     19, 12.8, false],
    ["Charlie", 21, 16.5, true ],
    ["Diana",   20, 14.0, false]
];

/* ── 1. le titre ── */
function afficherTitre() {
    console.log("=== SUIVI DES ATHLETES ===");
}
afficherTitre();

/* ── 2. afficher un athlète ──
   La DÉSTRUCTURATION rend au tableau des noms : au lieu de athlete[0],
   athlete[1]… on nomme les quatre cases en une ligne. C'est le remède au
   problème que pose cet exercice. */
function afficherAthlete(athlete) {
    const [nom, age, score, qualifie] = athlete;
    console.log("Nom : " + nom + " | Âge : " + age
                + " | Score : " + score + " | Qualifié : " + qualifie);
}
console.log("");
afficherAthlete(athletes[1]);

/* ── 3. parcourir, et compter les qualifiés ── */
console.log("");
let nbQualifies = 0;
for (const a of athletes) {
    afficherAthlete(a);
    if (a[3]) nbQualifies++;
}
console.log("Total qualifiés : " + nbQualifies);

/* ── 4. l'état de performance, en fléchée ──
   L'ordre des tests compte : si on écrivait « >= 14 » d'abord, un score
   de 16.5 y répondrait et on n'arriverait jamais à « Excellent ». On va
   donc du plus exigeant au moins exigeant. */
const etatPerformance = (score) =>
    score >= 16 ? "Excellent" :
    score >= 14 ? "Bon" :
                  "À améliorer";

console.log("");
athletes.forEach(([nom, , score]) => {
    /* La virgule vide saute l'âge : on ne nomme que ce dont on se sert. */
    console.log(nom + " (" + score + ") → " + etatPerformance(score));
});

/* ── 5. rechercher un athlète ── */
function rechercherAthlete(nom) {
    /* find() rend le PREMIER élément qui satisfait le test, ou undefined.
       Avec une boucle, il faudrait une variable et un « break ». */
    const trouve = athletes.find((a) => a[0].toLowerCase() === nom.toLowerCase());
    if (!trouve) {
        console.log("Aucun athlète trouvé");
        return;
    }
    afficherAthlete(trouve);
}
console.log("");
rechercherAthlete("charlie");
rechercherAthlete("Zoé");

/* ── 6. la moyenne des scores, à deux décimales ── */
function scoreMoyen(liste) {
    const somme = liste.reduce((t, a) => t + a[2], 0);
    return somme / liste.length;
}
console.log("");
console.log("Score moyen : " + scoreMoyen(athletes).toFixed(2));

