/* ═══════════════════════════════════════════════════════════════════
   TP 3 — Manipulation du DOM. Les 22 questions, numérotées comme dans
   le sujet.

   Une règle à retenir d'abord : le script est chargé À LA FIN du body.
   S'il était dans le <head>, document.querySelector("#titre") rendrait
   null — l'élément n'existerait pas encore. C'est l'erreur n° 1 du TP.
   ═══════════════════════════════════════════════════════════════════ */

/* ── Exercice 1 : sélectionner (questions 1 à 3) ────────────────── */

const titre       = document.querySelector("#titre");        // 1.
const description = document.querySelector("#description");  // 2.
const btnChanger  = document.querySelector("#btnChanger");   // 3.

/* querySelector() prend un sélecteur CSS : « #titre » pour un id,
   « .miniature » pour une classe. getElementById("titre") marche aussi,
   mais il ne sait faire QUE les id — un seul outil pour tout, c'est
   querySelector. */

/* ── Exercice 2 : modifier le contenu (questions 4 à 7) ─────────── */

btnChanger.addEventListener("click", function () {   // 4.
    titre.textContent = "Contenu modifié !";         // 5.
    description.textContent =                        // 6.
        "Le titre, ce paragraphe et le fond ont changé au clic.";
    document.body.style.backgroundColor = "#dcebf5"; // 7.

    /* textContent et non innerHTML : innerHTML interprète les balises.
       Si le texte venait d'un utilisateur, il pourrait contenir du HTML
       — et donc du <script>. textContent écrit du TEXTE, point. */
});

/* ── Exercice 3 : ajouter un commentaire (questions 8 à 15) ─────── */

const champ  = document.querySelector("#commentaire");        // 8.
const btnAjouter = document.querySelector("#btnAjouter");     // 9.
const liste  = document.querySelector("#listeCommentaires");  // 10.

btnAjouter.addEventListener("click", function () {
    const texte = champ.value.trim();                         // 11.

    /* trim() enlève les espaces aux deux bouts. Sans ce test, un clic sur
       un champ vide ajoute une ligne vide à la liste. */
    if (texte === "") {
        champ.focus();
        return;
    }

    const li = document.createElement("li");                  // 12.
    li.textContent = texte;                                   // 13.
    liste.appendChild(li);                                    // 14.

    champ.value = "";                                         // 15.
    champ.focus();
});

/* Entrée vaut le bouton : on tape un commentaire et on valide au clavier.
   Le sujet ne le demandait pas — c'est le premier reproche qu'on reçoit
   si on l'oublie. */
champ.addEventListener("keydown", function (e) {
    if (e.key === "Enter") btnAjouter.click();
});

/* ── Exercice 4 : supprimer un commentaire (questions 16 et 17) ── */

/* L'écouteur est posé sur la LISTE, pas sur chaque <li>.
   Pourquoi : les <li> n'existent pas encore au chargement. Poser
   l'écouteur sur chacun obligerait à le refaire à chaque ajout. Là,
   l'événement remonte de l'enfant jusqu'à la liste (on appelle cela la
   DÉLÉGATION), et un <li> créé dans dix minutes sera couvert lui aussi. */
liste.addEventListener("click", function (e) {                // 16.
    if (e.target.tagName === "LI") {
        e.target.remove();
    }
});
// 17. — testez : ajoutez trois commentaires, cliquez sur le deuxième.

/* ── Exercice 5 : la galerie (questions 18 à 22) ────────────────── */

const grande = document.querySelector("#grandeImage");            // 18.
const miniatures = document.querySelectorAll(".miniature");       // 19.

/* querySelectorAll rend une LISTE (une NodeList). Il faut la parcourir :
   lui parler directement, comme à un seul élément, ne marche pas. */
miniatures.forEach(function (mini) {                              // 20.
    mini.addEventListener("click", function () {                  // 21.
        grande.src = mini.dataset.grande || mini.src;             // 22.
        grande.alt = "Agrandissement de : " + mini.alt;

        /* Et on marque celle qui est choisie : on retire la classe de
           toutes, on la met sur une seule. */
        miniatures.forEach((m) => m.classList.remove("active"));
        mini.classList.add("active");
    });
});

/* data-grande : la miniature porte l'adresse de la grande image dans un
   attribut « data- ». Dans le sujet, la miniature et la grande image
   étaient le même fichier ; en vrai on affiche une petite version et on
   charge la grande au clic, et c'est à ça que sert data-. */

miniatures[0].classList.add("active");
console.log("TP 3 — DOM prêt. " + miniatures.length + " miniatures branchées.");

