/* ═══════════════════════════════════════════════════════════════════
   TP 4 — Valider un formulaire. Les 8 questions du sujet.

   « novalidate » est posé sur le <form> dans index.html : sans lui, le
   navigateur validerait lui-même le champ type="email" et on ne verrait
   jamais notre propre code travailler. C'est volontaire — ici on écrit
   la validation, on ne la délègue pas.
   ═══════════════════════════════════════════════════════════════════ */

/* ── Partie 1 : sélectionner le formulaire (questions 1 et 2) ───── */

const form = document.querySelector("#form");          // 1.

form.addEventListener("submit", function (e) {         // 2.

    /* ── Partie 2 : récupérer les valeurs (question 3) ──────────── */

    const nom      = document.querySelector("#nom").value.trim();
    const email    = document.querySelector("#email").value.trim();
    const password = document.querySelector("#password").value;

    /* trim() sur le nom et le courriel : un espace n'est pas un nom.
       Mais PAS sur le mot de passe — un espace y est un caractère
       légitime, et le couper changerait le mot de passe de
       l'utilisateur. */

    /* ── Partie 3 : la variable de validation (question 4) ──────── */

    let valide = true;

    /* « Pourquoi utilise-t-on cette variable ? »
       Pour vérifier TOUS les champs avant de décider. Si l'on sortait au
       premier problème (avec un return), l'utilisateur corrigerait le
       nom, renverrait, découvrirait le problème d'email, corrigerait,
       renverrait… Un seul envoi doit montrer tous les problèmes à la
       fois. La variable sert à retenir « il y a eu au moins une faute »
       tout en continuant à regarder les autres. */

    /* On remet à zéro les messages du coup précédent, sinon une erreur
       corrigée resterait affichée. */
    for (const id of ["Nom", "Email", "Password"]) {
        document.querySelector("#erreur" + id).textContent = "";
    }
    for (const id of ["nom", "email", "password"]) {
        document.querySelector("#" + id).classList.remove("faux");
    }
    document.querySelector("#succes").hidden = true;

    /* ── Partie 4 : le nom (question 5) ─────────────────────────── */

    if (nom === "") {
        document.querySelector("#erreurNom").textContent = "Nom obligatoire";
        document.querySelector("#nom").classList.add("faux");
        valide = false;
    }

    /* ── Partie 5 : le mot de passe (question 6) ────────────────── */

    if (password.length < 8) {
        document.querySelector("#erreurPassword").textContent = "8 caractères minimum";
        document.querySelector("#password").classList.add("faux");
        valide = false;
    }

    /* ── Partie 6 : le courriel (question 7) ────────────────────── */

    if (!email.includes("@")) {
        document.querySelector("#erreurEmail").textContent = "Email invalide";
        document.querySelector("#email").classList.add("faux");
        valide = false;
    }

    /* Le sujet demande « contient un @ », et c'est le bon exercice.
       Mais sachez que « a@b » passe ce test, et que « @ » tout seul
       aussi. Un test un peu plus sérieux ressemblerait à :
           /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)
       — quelque chose, un @, quelque chose, un point, quelque chose.
       Et même cette expression laisse passer des adresses qui
       n'existent pas : la SEULE vérification qui prouve qu'une adresse
       est bonne, c'est de lui envoyer un message. */

    /* ── Partie 7 : bloquer l'envoi (question 8) ────────────────── */

    if (!valide) {
        e.preventDefault();

        /* « Pourquoi utilise-t-on cette méthode ? »
           Parce que l'événement « submit » a un comportement PAR DÉFAUT :
           le navigateur part envoyer le formulaire et quitte la page.
           preventDefault() annule ce comportement — notre code a tourné,
           il a dit non, et la page reste là avec les messages d'erreur.
           Sans cet appel, les messages s'afficheraient une fraction de
           seconde avant que la page ne change. */

        /* Et on amène le curseur sur le premier champ fautif : c'est là
           que l'utilisateur doit agir. */
        const premier = document.querySelector("input.faux");
        if (premier) premier.focus();
        return;
    }

    /* Tout est bon. Ici, un vrai formulaire partirait vers le serveur ;
       dans cet outil il n'y a personne au bout, donc on annule aussi et
       on affiche le succès. */
    e.preventDefault();
    document.querySelector("#succes").hidden = false;
    console.log("Formulaire valide — nom : " + nom + ", email : " + email);
});

/* À retenir, et ce n'est pas dans le sujet : cette validation est pour
   le CONFORT de l'utilisateur, pas pour la sécurité. N'importe qui peut
   ouvrir les outils du navigateur et supprimer ce script. La
   vérification qui compte se fait côté SERVEUR — c'est le TP 3 de PHP. */
